import json, urllib.request, sys, os
key=os.environ["OPENALEX_API_KEY"]
for doi in sys.argv[1:]:
    try:
        d=json.load(urllib.request.urlopen(f"https://api.openalex.org/works/doi:{doi}?api_key={key}", timeout=30))
    except Exception as e:
        print("ERR", doi, e); continue
    inv=d.get("abstract_inverted_index") or {}
    pos={}
    for w,ps in inv.items():
        for p in ps: pos[p]=w
